CREATE ROLE stock_app LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT PASSWORD :[REDACTED]]];
CREATE ROLE auditor LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT PASSWORD :[REDACTED]]];
REVOKE ALL ON DATABASE branch_stock FROM PUBLIC;
GRANT CONNECT ON DATABASE branch_stock TO stock_app, auditor;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO stock_app, auditor;
GRANT SELECT (sku, quantity), UPDATE (quantity) ON stock TO stock_app;
GRANT SELECT ON stock, supplier_costs TO auditor;
SQL
unset stock_pw auditor_pw; printf 'credentials_generated=yes\n'; stat -c '%n mode=%a owner=%U:%G bytes=%s' /root/branch_stock-credentials/*.pgpass; cat /tmp/branch_stock_import.log

PGPASSFILE=/etc/branch_stock/stock_app.pgpass psql -X -v ON_ERROR_STOP=1 -h 10.100.105.10 -U stock_app -d branch_stock <<'SQL'
SELECT current_user, sku, quantity FROM stock ORDER BY sku;
BEGIN;
UPDATE stock SET quantity = quantity + 1 WHERE sku = 'PAPER' RETURNING sku, quantity;
ROLLBACK;
SELECT sku, quantity FROM stock WHERE sku = 'PAPER';
SQL

